        // cordova.js; native calls work after Cordova's "deviceready" (a sticky event: a late listener
        // still runs).
        if (window.cordova && typeof window.cordova.exec === "function")
            document.addEventListener("deviceready", function () {
                window.cordova.exec(function () { self.native = true; }, function () { self.native = false; }, "MDZHost", "probe", []);
            }, false);
        var api = window.MDZNet = window.MDZNet || {};
